typedef unsigned int nslSourceId;

#define NSL_INVALID_ID 0
#define assert(expression) ((void)0)

extern "C" void *memcpy(void *, const void *, unsigned int);
extern "C" char *strchr(const char *, int);
extern "C" char *strtok(char *, const char *);

struct nglFileBuf
{
    unsigned char *Buf;
    unsigned int Size;
    unsigned int UserData;
};

bool KSReadFile(const char *, nglFileBuf *, unsigned int);
void KSReleaseFile(nglFileBuf *);
nslSourceId nslLoadSource(const char *);

enum EventType
{
    SS_LAST = 105
};

class SoundScriptManager
{
    static SoundScriptManager *instance;

public:
    static inline SoundScriptManager *inst() { return instance; }
    bool createMapping(EventType, nslSourceId);
};

void SOUNDDATA_Load(void)
{
    nglFileBuf F;
    char *lineptr, *word, *s, *eol;
    char line[2000];
    KSReadFile("sounddata.dat", &F, 1);
    s = (char *) F.Buf;
    lineptr = s;

    for(int i = 0; i < SS_LAST; i++)
    {
         eol = strchr(lineptr, '\n');
         assert(lineptr < (char *)(F.Buf + F.Size));
         assert (eol-lineptr < 1999);
         memcpy(line, lineptr, eol-lineptr);
         line[eol-lineptr-1] = '\0';
         word = strtok(line," ,\t\n");
         while (word)
         {
              nslSourceId s = nslLoadSource(word);
              if (s != NSL_INVALID_ID) SoundScriptManager::inst()->createMapping((EventType)i, s);
              word = strtok(NULL, " ,\t\n");
         }
         lineptr = eol + 1;
    }
    KSReleaseFile(&F);
}
